class Solution {
public:
    double findMaxAverage(vector<int>& a, int k) {
        long long win = 0, best = LLONG_MIN;
        for (int i = 0; i < (int)a.size(); i++) {
            win += a[i];
            if (i >= k) win -= a[i - k];
            if (i >= k - 1) best = max(best, win);
        }
        return (double)best / k;
    }
};
