class Solution {
    bool v(char c) { return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u'; }
public:
    int maxVowels(string s, int k) {
        int cnt = 0, best = 0;
        for (int i = 0; i < (int)s.size(); i++) {
            cnt += v(s[i]);
            if (i >= k) cnt -= v(s[i - k]);
            if (i >= k - 1) best = max(best, cnt);
        }
        return best;
    }
};
