class Solution {
public:
    vector<int> getAverages(vector<int>& a, int k) {
        int n = a.size();
        long long w = 2LL * k + 1, sum = 0;
        vector<int> out(n, -1);
        for (int i = 0; i < n; i++) {
            sum += a[i];
            if (i >= w) sum -= a[i - w];
            if (i >= w - 1) out[i - k] = (int)(sum / w);
        }
        return out;
    }
};
