class Solution {
public:
    int numOfSubarrays(vector<int>& a, int k, int threshold) {
        long long target = 1LL * threshold * k, sum = 0;
        int cnt = 0;
        for (int i = 0; i < (int)a.size(); i++) {
            sum += a[i];
            if (i >= k) sum -= a[i - k];
            if (i >= k - 1 && sum >= target) cnt++;
        }
        return cnt;
    }
};
